create or replace function public.maths_get_home_snapshot() returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,maths as $$ declare uid uuid:=maths._require_uid(); day_ int:=maths._study_day(); daily maths.sessions%rowtype; target_ int; done_ int; resume_ jsonb; ids text[]; config jsonb; begin config:=jsonb_build_object('dailyTarget',coalesce(nullif(maths._setting('daily_chapter_size','25'),'')::int,25),'newQuota',coalesce(nullif(maths._setting('daily_new_quota','7'),'')::int,7),'difficultRotationDays',coalesce(nullif(maths._setting('difficult_rotation_days','3'),'')::int,3),'practiceMoreSize',coalesce(nullif(maths._setting('practice_more_size','20'),'')::int,20),'timezone',maths._setting('study_timezone','Asia/Kolkata')); select * into daily from maths.sessions s where s.user_id=uid and lower(coalesce(s.mode,''))='daily' and coalesce(nullif(s.params->>'planDay','')::int,0)=day_ order by s.completed desc,s.updated_at desc nulls last limit 1; target_:=coalesce((select count(*) from maths.session_questions where session_id=daily.session_id),(config->>'dailyTarget')::int); done_:=case when daily.session_id is null then 0 else (select count(distinct a.question_id) from maths.attempts a where a.user_id=uid and a.session_id=daily.session_id) end; select jsonb_build_object('sessionId',s.session_id,'title',s.title,'mode',s.mode,'currentIndex',s.current_index,'target',(select count(*) from maths.session_questions sq where sq.session_id=s.session_id)) into resume_ from maths.sessions s where s.user_id=uid and not s.completed order by s.updated_at desc nulls last limit 1; select coalesce(array_agg(r.question_id),array[]::text[]) into ids from maths._user_runtime(uid) r where r.academic_eligible; return jsonb_build_object('ok',true,'studyDay',day_,'config',config,'daily',jsonb_build_object('target',target_,'done',least(done_,target_),'remaining',greatest(0,target_-done_),'completed',coalesce(daily.completed,false),'sessionId',coalesce(daily.session_id,''),'composition',coalesce(daily.params->'dailyComposition','null'::jsonb)),'resume',resume_,'overall',maths._metric(uid,ids),'counts',jsonb_build_object('new',(select count(*) from maths._user_runtime(uid) r where r.academic_eligible and r.state_attempts=0),'starred',(select count(*) from maths._user_runtime(uid) r where r.academic_eligible and r.starred and not r.mastered),'concepts',(select count(*) from maths.concept_membership c where c.user_id=uid and c.active),'mocks',(select count(*) from maths.practice_set_items where set_id='MOCK_QUESTIONS'),'formulas',(select count(*) from maths.practice_set_items where set_id='MOCK_FORMULA_REVISION'),'calculation',(select count(*) from maths._user_runtime(uid) r where r.runtime_active and (r.bank_calculation or r.in_calc_set)))); end $$;
create or replace function public.maths_get_chapters_hub() returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,maths as $$ declare uid uuid:=maths._require_uid(); body jsonb; begin with r as(select * from maths._user_runtime(uid) where academic_eligible), chapters as(select chapter,group_key,array_agg(question_id) ids from r group by chapter,group_key), rows as(select chapter,group_key,maths._metric(uid,ids) metric from chapters) select jsonb_build_object('ok',true,'groups',jsonb_build_array(jsonb_build_object('key','advanced','label','Advanced','metric',maths._metric(uid,(select coalesce(array_agg(question_id),array[]::text[]) from r where group_key='advanced'))),jsonb_build_object('key','arithmetic','label','Arithmetic','metric',maths._metric(uid,(select coalesce(array_agg(question_id),array[]::text[]) from r where group_key='arithmetic'))),jsonb_build_object('key','misc','label','MISC','metric',maths._metric(uid,(select coalesce(array_agg(question_id),array[]::text[]) from r where group_key='misc')))),'chapters',coalesce((select jsonb_agg(jsonb_build_object('chapter',chapter,'group',group_key,'metric',metric) order by case group_key when 'advanced' then 1 when 'arithmetic' then 2 else 3 end,chapter) from rows),'[]'::jsonb)) into body; return body; end $$;
create or replace function public.maths_get_chapter(p_chapter text,p_topic text default null) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,maths as $$ declare uid uuid:=maths._require_uid(); ids text[]; topics jsonb; begin select coalesce(array_agg(question_id),array[]::text[]) into ids from maths._user_runtime(uid) r where r.academic_eligible and maths._norm(r.chapter)=maths._norm(p_chapter) and (p_topic is null or maths._norm(r.major_topic)=maths._norm(p_topic) or maths._norm(r.topic)=maths._norm(p_topic)); select coalesce(jsonb_agg(jsonb_build_object('name',major_topic,'metric',maths._metric(uid,tids)) order by ord,major_topic),'[]'::jsonb) into topics from(select major_topic,array_agg(question_id) tids,case major_topic when 'Lines & Angles' then 1 when 'Triangle' then 2 when 'Circle' then 3 when 'Quadrilateral & Polygon' then 4 when 'Quadrilateral' then 2 when 'Polygon' then 4 when 'Paths / Composite 2D' then 5 when 'Cuboid & Cube' then 1 when 'Cylinder' then 2 when 'Cone & Frustum' then 3 when 'Sphere & Hemisphere' then 4 when 'Prism & Pyramid' then 5 when 'Composite Solids' then 6 when 'Profit & Loss' then 1 when 'Dishonest Sellers' then 2 when 'Discount' then 3 else 99 end ord from maths._user_runtime(uid) r where r.academic_eligible and maths._norm(r.chapter)=maths._norm(p_chapter) group by major_topic)x; return jsonb_build_object('ok',true,'chapter',p_chapter,'topic',p_topic,'metric',maths._metric(uid,ids),'topics',topics); end $$;
create or replace function public.maths_get_progress() returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,maths as $$ declare uid uuid:=maths._require_uid(); ids text[]; chapters jsonb; begin select coalesce(array_agg(question_id),array[]::text[]) into ids from maths._user_runtime(uid) where academic_eligible; select coalesce(jsonb_agg(jsonb_build_object('chapter',chapter,'group',group_key,'metric',maths._metric(uid,cids)) order by chapter),'[]'::jsonb) into chapters from(select chapter,group_key,array_agg(question_id)cids from maths._user_runtime(uid) where academic_eligible group by chapter,group_key)x; return jsonb_build_object('ok',true,'overall',maths._metric(uid,ids),'advanced',maths._metric(uid,(select coalesce(array_agg(question_id),array[]::text[]) from maths._user_runtime(uid) where academic_eligible and group_key='advanced')),'arithmetic',maths._metric(uid,(select coalesce(array_agg(question_id),array[]::text[]) from maths._user_runtime(uid) where academic_eligible and group_key='arithmetic')),'misc',maths._metric(uid,(select coalesce(array_agg(question_id),array[]::text[]) from maths._user_runtime(uid) where academic_eligible and group_key='misc')),'chapters',chapters); end $$;
create or replace function public.maths_get_mocks_hub() returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,maths as $$ declare uid uuid:=maths._require_uid(); ids text[]; chapters jsonb; begin select coalesce(array_agg(question_id),array[]::text[]) into ids from maths._user_runtime(uid) where runtime_active and in_mock; select coalesce(jsonb_agg(jsonb_build_object('chapter',chapter,'metric',maths._metric(uid,cids)) order by (maths._metric(uid,cids)->>'wrong')::int desc,chapter),'[]'::jsonb) into chapters from(select chapter,array_agg(question_id)cids from maths._user_runtime(uid) where runtime_active and in_mock group by chapter)x; return jsonb_build_object('ok',true,'setId','MOCK_QUESTIONS','overall',maths._metric(uid,ids),'chapters',chapters); end $$;
create or replace function public.maths_get_formula_hub() returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,maths as $$ declare uid uuid:=maths._require_uid(); ids text[]; chapters jsonb; begin select coalesce(array_agg(question_id),array[]::text[]) into ids from maths._user_runtime(uid) where runtime_active and in_formula_revision; select coalesce(jsonb_agg(jsonb_build_object('chapter',chapter,'metric',maths._metric(uid,cids)) order by chapter),'[]'::jsonb) into chapters from(select chapter,array_agg(question_id)cids from maths._user_runtime(uid) where runtime_active and in_formula_revision group by chapter)x; return jsonb_build_object('ok',true,'setId','MOCK_FORMULA_REVISION','overall',maths._metric(uid,ids),'due',(select count(*) from maths._user_runtime(uid) r where r.question_id=any(ids) and (r.state_attempts=0 or r.profile_last_result='wrong' or r.difficult or (r.profile_total>0 and r.age_days>=r.review_interval))),'chapters',chapters); end $$;
create or replace function maths._calc_type(r maths.runtime_questions) returns text language plpgsql immutable as $$ declare ch text:=maths._norm(r.chapter); ct text:=maths._norm(r.card_type); tg text:=maths._norm(r.template_group); vt text:=maths._norm(r.variant_types); sf text:=maths._norm(r.source_file); begin if ct='drill' or vt~'drill' or sf~'(pdf drill|class practice|homework practice)' then return'DRILL'; end if; if ct in ('method','concept','formula') or ct~'(method|shortcut|rule)' then return'METHOD'; end if; if ch='calculation memory' or ct='memory' or tg~'^(square_[0-9]+|cube_[0-9]+|table_[0-9]+|fraction_percent|power_|root_|triplet_)' then return'MEMORY'; end if; return'DRILL'; end $$;
create or replace function maths._calc_recall_eligible(r maths.runtime_questions) returns boolean language plpgsql immutable as $$ declare typ text:=maths._calc_type(r); skill text:=maths._norm(coalesce(r.topic,r.subtopic,'Mixed')); n int; a int; b int; m text; begin if typ<>'MEMORY' then return false; end if; if skill='squares' then begin n:=(regexp_match(r.prompt,'^\s*(\d+)'))[1]::int; exception when others then n:=null; end; return n is null or n>=17; end if; if skill='cubes' then begin n:=(regexp_match(r.prompt,'^\s*(\d+)'))[1]::int; exception when others then n:=null; end; return n is null or n>=10; end if; if skill='tables' then m:=replace(replace(replace(coalesce(r.prompt,''),'×','x'),'X','x'),'*','x'); begin a:=btrim(split_part(m,'x',1))::int; b:=(regexp_match(split_part(m,'x',2),'^\s*(\d+)'))[1]::int; exception when others then return false; end; if a between 12 and 19 then return b between 6 and 12; elsif a between 21 and 29 then return b between 3 and 12; elsif a=30 then return b between 1 and 5; elsif a between 31 and 40 then return b between 1 and 3; else return false; end if; end if; return true; end $$;
create or replace function public.maths_get_calculation_hub() returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,maths as $$ declare uid uuid:=maths._require_uid(); hub jsonb; begin with c as(select r.*,maths._calc_type(q) calc_type,coalesce(nullif(q.topic,''),nullif(q.subtopic,''),'Mixed') skill from maths._user_runtime(uid) r join maths.runtime_questions q using(question_id) where r.runtime_active and (r.bank_calculation or r.in_calc_set) and (maths._calc_type(q)<>'MEMORY' or maths._calc_recall_eligible(q))) select jsonb_build_object('ok',true,'total',count(*),'memory',count(*) filter(where calc_type='MEMORY'),'methods',count(*) filter(where calc_type='METHOD'),'drills',count(*) filter(where calc_type='DRILL'),'slow',count(*) filter(where last_response_sec>=8),'wrong',count(*) filter(where profile_last_result='wrong'),'skills',coalesce((select jsonb_agg(jsonb_build_object('skill',skill,'total',n,'memory',memory,'methods',methods,'drills',drills) order by skill) from(select skill,count(*) n,count(*)filter(where calc_type='MEMORY') memory,count(*)filter(where calc_type='METHOD') methods,count(*)filter(where calc_type='DRILL') drills from c group by skill)x),'[]'::jsonb)) into hub from c; return hub; end $$;
create or replace function public.maths_get_concepts_hub() returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,maths as $$ declare uid uuid:=maths._require_uid(); ids text[]; chapters jsonb; begin select coalesce(array_agg(r.question_id),array[]::text[]) into ids from maths._user_runtime(uid) r join maths.concept_membership c on c.user_id=uid and c.question_id=r.question_id and c.active where r.runtime_active; with c as(select r.chapter,r.major_topic,r.question_id from maths._user_runtime(uid) r join maths.concept_membership m on m.user_id=uid and m.question_id=r.question_id and m.active where r.runtime_active), topic_rows as(select chapter,major_topic,array_agg(question_id) tids from c group by chapter,major_topic), chapter_rows as(select chapter,array_agg(question_id) cids from c group by chapter) select coalesce(jsonb_agg(jsonb_build_object('chapter',cr.chapter,'metric',maths._metric(uid,cr.cids),'topics',coalesce((select jsonb_agg(jsonb_build_object('name',tr.major_topic,'metric',maths._metric(uid,tr.tids)) order by tr.major_topic) from topic_rows tr where tr.chapter=cr.chapter),'[]'::jsonb)) order by cr.chapter),'[]'::jsonb) into chapters from chapter_rows cr; return jsonb_build_object('ok',true,'metric',maths._metric(uid,ids),'chapters',chapters); end $$;
create or replace function public.maths_get_library_hub(p_cluster text default null) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,maths as $$ declare uid uuid:=maths._require_uid(); clusters jsonb; items jsonb:='[]'::jsonb; c text:=lower(coalesce(p_cluster,'')); begin with r as(select * from maths._user_runtime(uid) where runtime_active and not in_mock and not bank_calculation), x as(select 'formulas' key,count(*) n from r where maths._norm(card_type)='formula' union all select 'methods',count(*) from r where maths._norm(card_type) in('method','pattern','trap') union all select 'fractions',count(*) from r where maths._norm(chapter)='fraction patterns' union all select 'triplets',count(*) from r where maths._norm(chapter)='triplets' union all select 'marked',count(*) from r where starred union all select 'notes',count(*) from maths.user_notes n where n.user_id=uid and btrim(n.note)<>'' union all select 'recent',least(20,count(*)) from r) select jsonb_object_agg(key,n) into clusters from x; if c<>'' then select coalesce(jsonb_agg(jsonb_build_object('id',r.question_id,'chapter',r.chapter,'topic',r.topic,'prompt',r.prompt,'answer',r.answer,'explanation',r.explanation,'starred',r.starred,'difficult',r.difficult,'note',(select n.note from maths.user_notes n where n.user_id=uid and n.question_id=r.question_id)) order by r.added_at desc nulls last,r.question_id),'[]'::jsonb) into items from maths._user_runtime(uid) r where r.runtime_active and not r.in_mock and not r.bank_calculation and case c when 'formulas' then maths._norm(r.card_type)='formula' when 'methods' then maths._norm(r.card_type) in('method','pattern','trap') when 'fractions' then maths._norm(r.chapter)='fraction patterns' when 'triplets' then maths._norm(r.chapter)='triplets' when 'marked' then r.starred when 'notes' then exists(select 1 from maths.user_notes n where n.user_id=uid and n.question_id=r.question_id and btrim(n.note)<>'') when 'recent' then true else false end; end if; return jsonb_build_object('ok',true,'counts',coalesce(clusters,'{}'::jsonb),'cluster',p_cluster,'items',items); end $$;
create or replace function public.maths_get_demand_hub() returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,maths as $$ declare uid uuid:=maths._require_uid(); sets jsonb; begin select coalesce(jsonb_agg(jsonb_build_object('setId',s.set_id,'name',s.set_name,'description',coalesce(s.description,''),'status',s.status,'count',(select count(*) from maths.practice_set_items i where i.set_id=s.set_id),'specialist',s.set_id in('MOCK_QUESTIONS','MOCK_FORMULA_REVISION','CALC_TRAINING')) order by s.set_name),'[]'::jsonb) into sets from maths.practice_sets s where s.user_id=uid and lower(coalesce(s.status,'active'))<>'inactive'; return jsonb_build_object('ok',true,'sets',sets); end $$;
create or replace function public.maths_get_ondemand_hub() returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,maths as $$ declare uid uuid:=maths._require_uid(); d jsonb; begin d:=public.maths_get_demand_hub(); return jsonb_build_object('ok',true,'calculation',(select count(*) from maths._user_runtime(uid) r where r.runtime_active and (r.bank_calculation or r.in_calc_set)),'mocks',(select count(*) from maths.practice_set_items where set_id='MOCK_QUESTIONS'),'formulas',(select count(*) from maths.practice_set_items where set_id='MOCK_FORMULA_REVISION'),'concepts',(select count(*) from maths.concept_membership where user_id=uid and active),'generated',(select count(*) from maths._user_runtime(uid) where runtime_active and bank_generated),'demandSets',d->'sets'); end $$;


